    return;
  }
  isSessionActive.current = true;
  logDebugMessage(`[useRemoteSession] Initializing for session ${remoteSessionConfig.sessionId}`);
  let remoteSessionWebSocket = new SessionsWebSocket(remoteSessionConfig, {
    onMessage: incomingMessage => {
      let messageInfoParts = [`type=${incomingMessage.type}`];
      if ("subtype" in incomingMessage) {
        messageInfoParts.push(`subtype=${incomingMessage.subtype}`);
      }
      if (incomingMessage.type === "user") {
        let contentOrToolResults = incomingMessage.message?.content;
        messageInfoParts.push(`content=${Array.isArray(contentOrToolResults) ? contentOrToolResults.map(node => node.type).join(",") : typeof contentOrToolResults}`);
      }
      logDebugMessage(`[useRemoteSession] Received ${messageInfoParts.join(" ")}`);
      if (responseTimeoutRef.current) {
        clearTimeout(responseTimeoutRef.current);
        responseTimeoutRef.current = null;
      }
      if (incomingMessage.type === "user" && incomingMessage.uuid && echoedMessageBuffer.current.has(incomingMessage.uuid)) {
        let echoedMessageUuid = incomingMessage.uuid;
        updateMessages(messageList => {
          let lastIndex = messageList.findLastIndex(messageVal => messageVal.uuid === echoedMessageUuid);
          if (lastIndex === -1 || lastIndex === messageList.length - 1) {
            return messageList;
          }
          let targetMessage = messageList[lastIndex];
          return messageList.slice(0, lastIndex).concat(messageList.slice(lastIndex + 1), targetMessage);
        });
        logDebugMessage(`[useRemoteSession] Reconciled echoed user message ${echoedMessageUuid} to canonical position`);
        return;
      }
      if (incomingMessage.type === "system" && incomingMessage.subtype === "init") {
        logDebugMessage(`[useRemoteSession] Init received with ${incomingMessage.slash_commands.length} slash commands`);
        handleInit(incomingMessage);
      }
      if (incomingMessage.type === "system") {
        if (incomingMessage.subtype === "task_started") {
          activeTaskIds.current.add(incomingMessage.task_id);
          refreshBackgroundTaskCount();
          return;
        }
        if (incomingMessage.subtype === "task_notification") {
          activeTaskIds.current.delete(incomingMessage.task_id);
          refreshBackgroundTaskCount();
          return;
        }
        if (incomingMessage.subtype === "task_progress" || incomingMessage.subtype === "task_updated" || incomingMessage.subtype === "notification") {
          return;
        }
        if (incomingMessage.subtype === "status") {
          let previousCompactingState = isCompacting.current;
          isCompacting.current = incomingMessage.status === "compacting";
          if (previousCompactingState && isCompacting.current) {
            return;
          }
        }
        if (incomingMessage.subtype === "compact_boundary") {
          isCompacting.current = false;
        }
      }
      if (isResultEvent(incomingMessage)) {
        isCompacting.current = false;
        setLoadingState(false);
      }
      if (incomingMessage.type === "user") {
        let userMessageContent = incomingMessage.message?.content;
        if (Array.isArray(userMessageContent)) {
          let toolResultIds = [];
          for (let toolResultItem of userMessageContent) if (toolResultItem.type === "tool_result") {
            toolResultIds.push(toolResultItem.tool_use_id);
          }
          if (toolResultIds.length > 0) {
            updateInProgressToolUseIds({
              action: "remove",
              ids: toolResultIds
            });
          }
        }
      }
      let adaptedMessage = adaptMessage(incomingMessage, remoteSessionConfig.viewerOnly ? {
        convertToolResults: true,
        convertUserTextMessages: true
      } : undefined);
      if (adaptedMessage.type === "message") {
        updateStreamingToolUses(ensureEmptyArray => ensureEmptyArray.length > 0 ? [] : ensureEmptyArray);
        if (adaptedMessage.message.type === "assistant") {
          let previousCompactingState = adaptedMessage.message.message.content.filter(toolUse => toolUse.type === "tool_use").map(item => item.id);
          if (previousCompactingState.length > 0) {
            updateInProgressToolUseIds({
              action: "add",
              ids: previousCompactingState
            });
          }
        }
        updateMessages(messagesVal => [...messagesVal, adaptedMessage.message]);
      } else if (adaptedMessage.type === "stream_event") {
        handleEventStream(adaptedMessage.event, newMessage => updateMessages(messagesVal => [...messagesVal, newMessage]), () => {}, setStreamMode, updateStreamingToolUses, undefined, undefined, recordApiMetricsEvent);
      }
    },
    onPermissionRequest: (toolUse, remoteId) => {
      logDebugMessage(`[useRemoteSession] Permission request for tool: ${toolUse.tool_name}`);
      let toolDescriptor = findModuleByName(toolsRef.current, toolUse.tool_name) ?? createToolDescriptor(toolUse.tool_name);
      let assistantMessage = createAssistantMessage(toolUse, remoteId);
      let permissionResult = {
        behavior: "ask",
        message: toolUse.description ?? `${toolUse.tool_name} requires permission`,
        suggestions: toolUse.permission_suggestions,
        blockedPath: toolUse.blocked_path
      };
      let permissionContext = {
        assistantMessage: assistantMessage,
        tool: toolDescriptor,
        description: toolUse.description ?? `${toolUse.tool_name} requires permission`,
        input: toolUse.input,
        toolUseContext: {},
        toolUseID: toolUse.tool_use_id,
        permissionResult: permissionResult,
        permissionPromptStartTimeMs: Date.now(),
        onUserInteraction() {},
        onAbort() {
          let abortResponse = {
            behavior: "deny",
            message: "User aborted"
          };
          remoteSessionWebSocket.respondToPermissionRequest(remoteId, abortResponse);
          updateToolConfirmQueue(toolUses => toolUses.filter(record => record.toolUseID !== toolUse.tool_use_id));
        },
        onAllow(inputData, event, onAllowCallback) {
          let permissionPayload = {
            behavior: "allow",
            updatedInput: inputData
          };
          remoteSessionWebSocket.respondToPermissionRequest(remoteId, permissionPayload);
          updateToolConfirmQueue(toolUses => toolUses.filter(toolUseRecord => toolUseRecord.toolUseID !== toolUse.tool_use_id));
          setLoadingState(true);
        },
        onReject(errorReason) {
          let permissionResponse = {
            behavior: "deny",
            message: errorReason ?? "User denied permission"
          };
          remoteSessionWebSocket.respondToPermissionRequest(remoteId, permissionResponse);
          updateToolConfirmQueue(toolUses => toolUses.filter(toolUsage => toolUsage.toolUseID !== toolUse.tool_use_id));
        },
        async recheckPermission() {}
      };
      updateToolConfirmQueue(messagesVal => [...messagesVal, permissionContext]);
      setLoadingState(false);
    },
    onPermissionCancelled: (cancelReason, fallbackId) => {
      logDebugMessage(`[useRemoteSession] Permission request cancelled: ${cancelReason}`);
      let effectiveId = fallbackId ?? cancelReason;
      updateToolConfirmQueue(toolUses => toolUses.filter(record => record.toolUseID !== effectiveId));
      setLoadingState(true);
    },
    onConnected: () => {
      logDebugMessage("[useRemoteSession] Connected");
      updateRemoteConnectionStatus("connected");
    },
    onReconnecting: () => {
      logDebugMessage("[useRemoteSession] Reconnecting");
      updateRemoteConnectionStatus("reconnecting");
      activeTaskIds.current.clear();
      refreshBackgroundTaskCount();
      updateInProgressToolUseIds({
        action: "clear"
      });
    },
    onDisconnected: () => {
      logDebugMessage("[useRemoteSession] Disconnected");
      updateRemoteConnectionStatus("disconnected");
      setLoadingState(false);
      activeTaskIds.current.clear();
      refreshBackgroundTaskCount();
      updateInProgressToolUseIds({
        action: "clear"
      });
    },
    onError: error => {
      logDebugMessage(`[useRemoteSession] Error: ${error.message}`);
    }
  });
  sessionWebSocket.current = remoteSessionWebSocket;
  remoteSessionWebSocket.connect();
  return () => {
    logDebugMessage("[useRemoteSession] Cleanup - disconnecting");
    if (responseTimeoutRef.current) {
      clearTimeout(responseTimeoutRef.current);
      responseTimeoutRef.current = null;
    }
    remoteSessionWebSocket.disconnect();
    sessionWebSocket.current = null;
  };
}

